// Roz ka ads run — pehle brain ka plan dekho (dailyAd), na mile to
// DIGITAL_ADS_QUEUE_JSON se rotate karo (day-of-year % queue length).
// Brain down ho ya plan na ho to queue fallback kabhi block nahi karta.
const planJson = $('get-plan').first().json;
const plan = (planJson && planJson.data && planJson.data.plan) || (planJson && planJson.plan) || null;
const publish = String($env.DIGITAL_ADS_AUTO_PUBLISH || 'false').toLowerCase() === 'true';
const ad = plan && plan.dailyAd ? plan.dailyAd : null;
if (ad && ad.productType && ad.productName && ad.productLink) {
  const payload = { productType: ad.productType, productName: ad.productName, productLink: ad.productLink, publish };
  if (ad.productDescription) payload.productDescription = ad.productDescription;
  return [{ json: { ok: true, payload, source: 'brain', score: plan.slots && plan.slots[0] ? plan.slots[0].score : null } }];
}
const raw = $env.DIGITAL_ADS_QUEUE_JSON || '[]';
let queue = [];
try { queue = JSON.parse(raw); } catch (e) { queue = []; }
if (!Array.isArray(queue) || !queue.length) {
  return [{ json: { ok: false,
    reason: 'Brain plan me dailyAd nahi aur DIGITAL_ADS_QUEUE_JSON khaali hai — products ki list env me set karo.' } }];
}
const dayIdx = Math.floor(Date.now() / 86400000);
const item = queue[dayIdx % queue.length] || {};
const payload = { productType: item.productType, productName: item.productName,
  productLink: item.productLink, publish };
if (item.topic) payload.topic = item.topic;
if (item.niche) payload.niche = item.niche;
if (!payload.productType || !payload.productName || !payload.productLink) {
  return [{ json: { ok: false, reason: 'Queue item me productType/productName/productLink zaroori hai.' } }];
}
return [{ json: { ok: true, payload, source: 'queue', queueSize: queue.length, dayIndex: dayIdx % queue.length } }];

const j = $input.first().json;
console.log(JSON.stringify({ event: 'digital_ads_daily', ok: j.ok,
  product: j.payload?.productName ?? null, reason: j.reason ?? null,
  at: new Date().toISOString() }));
return [{ json: j }];
